// Display-only enum names. The wire carries numbers; these labels exist
// so the debug pane is readable and are not authoritative metadata.
const MAV_TYPE = {
  0: 'GENERIC', 1: 'FIXED_WING', 2: 'QUADROTOR', 3: 'COAXIAL', 4: 'HELICOPTER',
  5: 'ANTENNA_TRACKER', 6: 'GCS', 7: 'AIRSHIP', 8: 'FREE_BALLOON', 9: 'ROCKET',
  10: 'GROUND_ROVER', 11: 'SURFACE_BOAT', 12: 'SUBMARINE', 13: 'HEXAROTOR',
  14: 'OCTOROTOR', 15: 'TRICOPTER', 18: 'ONBOARD_CONTROLLER'
};
const MAV_AUTOPILOT = { 0: 'GENERIC', 3: 'ARDUPILOTMEGA', 8: 'INVALID', 12: 'PX4' };
const MAV_STATE = {
  0: 'UNINIT', 1: 'BOOT', 2: 'CALIBRATING', 3: 'STANDBY', 4: 'ACTIVE',
  5: 'CRITICAL', 6: 'EMERGENCY', 7: 'POWEROFF', 8: 'FLIGHT_TERMINATION'
};
const GPS_FIX = {
  0: 'NO_GPS', 1: 'NO_FIX', 2: '2D_FIX', 3: '3D_FIX', 4: 'DGPS',
  5: 'RTK_FLOAT', 6: 'RTK_FIXED', 7: 'STATIC', 8: 'PPP'
};

const name = (table, v) => (v === null || v === undefined) ? '—' : (table[v] || String(v)) + ' (' + v + ')';
const num = (v, unit) => (v === null || v === undefined) ? '—' : v + (unit || '');

const peers = Array.isArray(msg.payload) ? msg.payload : [];
const lines = [];

if (!peers.length) {
  lines.push('peer table is empty — nothing has been heard yet');
}

for (const peer of peers) {
  lines.push('SYSTEM ' + peer.sysid + '  (' + peer.components.length + ' component(s))');
  for (const c of peer.components) {
    lines.push('  component ' + c.compid + '   [' + c.state + ']' + (c.mismatch ? '  *** PROFILE MISMATCH ***' : ''));
    lines.push('    identity   type=' + name(MAV_TYPE, c.type) + '  autopilot=' + name(MAV_AUTOPILOT, c.autopilot));
    lines.push('    mode       status=' + name(MAV_STATE, c.systemStatus) + '  armed=' + (c.armed === null ? '—' : c.armed) + '  flightMode=' + num(c.flightMode));

    const ages = Object.entries(c.sections || {});
    lines.push('    heard      ' + (ages.length ? ages.map(([k, v]) => k + ' ' + v + 'ms ago').join(', ') : '—'));

    if (c.position) {
      lines.push('    position   ' + c.position.lat.toFixed(7) + ', ' + c.position.lon.toFixed(7) +
        '  alt=' + num(c.position.alt, 'm') + '  rel=' + num(c.position.relativeAlt, 'm') +
        '  hdg=' + num(c.position.heading, '°'));
    } else {
      lines.push('    position   — (no GLOBAL_POSITION_INT yet)');
    }

    lines.push('    gps        ' + (c.gps ? name(GPS_FIX, c.gps.fixType) + '  sats=' + num(c.gps.satellites) : '—'));
    lines.push('    battery    ' + (c.battery ? 'id=' + num(c.battery.id) + ' volts=' + num(c.battery.voltage, 'V') +
      ' remaining=' + num(c.battery.remaining, '%') + ' current=' + num(c.battery.current, 'A') : '—'));
    lines.push('    home       ' + (c.home ? c.home.lat.toFixed(7) + ', ' + c.home.lon.toFixed(7) + '  alt=' + num(c.home.alt, 'm') : '—'));

    const eps = c.endpoints || [];
    lines.push('    endpoints  ' + (eps.length
      ? eps.map((e) => e.address + ':' + e.port + (e.primary ? ' (primary)' : '')).join(', ')
      : '—'));

    const st = c.statustext || [];
    lines.push('    statustext ' + (st.length ? st.length + ' retained, latest: ' + JSON.stringify(st[st.length - 1]) : '—'));
  }
}

node.status({ fill: peers.length ? 'green' : 'grey', shape: 'dot', text: peers.length + ' system(s)' });

// payload keeps the structured snapshot; `text` is the rendered view.
return { payload: msg.payload, text: lines.join('\n') };
